 "content": "def transform(grid):
    """Restore blank cells from the global 9-color diagonal cycle."""
    h, w = len(grid), len(grid[0])
    # The undamaged background advances one step right and one step down.
    # Infer the global phase by voting over intact ordinary cells.
    votes = [0] * 9
    for r in range(h):
        for c in range(w):
